package com.clubmanager.util;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;


// every method here either returns the clean value OR throws an error message in a popup generated by MembersPanel
public class Validator {

    // so this is a "pattern" of regex (regular expressions), basically this is a simpler way to set formats of characters, esp special characters like @ and $, it follows a specific naming convention and we use that to define email formats
    private static final String EMAIL_PATTERN = "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$";

    // this pattern allows only letters in any language, spaces, dots, apostrophes and hyphens, but no numbers, alphanumerics or aything not fitting an email form
    private static final String NAME_PATTERN = "^[\\p{L} .'-]+$";

    // this pattern matches the format of DECIMAL(4,2) in MySQL:one or two dogits, then a dot, then one or two digits
    private static final String GROUP_PATTERN = "^\\d{1,2}(\\.\\d{1,2})?$";

    
    private Validator() {
    }

    // this function checks a text field, and ensures it's not empty or too long, then returns the text. It then trims the space/empty input
    public static String requireText(String value, String fieldName, int maxLength) {
        String trimmed = (value == null) ? "" : value.trim();   // null or spaces only both count as empty

        if (trimmed.isEmpty()) {
            throw new IllegalArgumentException(fieldName + " cannot be empty.");
        }
        if (trimmed.length() > maxLength) {
            // Throws an error message if the input is too long, with the maximum specified
            throw new IllegalArgumentException(fieldName + " is too long (maximum " + maxLength + " characters).");
        }
        return trimmed;
    }

    // so this checks the name is not empty, not too long and doesn't have foreign characters
    public static String validateName(String value) {
        String name = requireText(value, "Full name", 60);
        if (!name.matches(NAME_PATTERN)) {
            throw new IllegalArgumentException("Full name can only contain letters, spaces, dots, apostrophes and hyphens.");
        }
        return name;
    }

    // email error handler, it makes sure the email isn't too long and whether it fits correct format
    public static String validateEmail(String value) {
        String email = requireText(value, "Email", 100);
        if (!email.matches(EMAIL_PATTERN)) {
            throw new IllegalArgumentException("Email is not valid. Example: name@example.com");
        }
        return email;
    }

    // this turns the year text into a whole number
    public static int parseYear(String value) {
        String text = requireText(value, "Year of study", 10);
        int year;
        try {
            year = Integer.parseInt(text);   // throws NumberFormatException for things like "two" or "2.5"
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException("Year of study must be a whole number, e.g. 2.");
        }
        if (year < 1 || year > 6) {
            throw new IllegalArgumentException("Year of study must be between 1 and 6.");
        }
        return year;
    }

    // this first checks whether the text matches the decimal form, then converts it to decimal
    public static double parseGroup(String value) {
        String text = requireText(value, "Candidate group", 10);
        if (!text.matches(GROUP_PATTERN)) {
            throw new IllegalArgumentException("Candidate group must be a number like 2 or 2.2 (at most 2 digits before and 2 after the decimal point).");
        }
        return Double.parseDouble(text);   
    }

    // date input validation, where it takes the text and converts it to a local date format. It also ensures the dates are not in the future
    public static LocalDate parseDate(String value) {
        String text = requireText(value, "Date joined", 10);
        LocalDate date;
        try {
            date = LocalDate.parse(text);   // only accepts real dates in YYYY-MM-DD, so 2026-02-30 fails too
        } catch (DateTimeParseException ex) {
            throw new IllegalArgumentException("Date joined must be a real date in the format YYYY-MM-DD, e.g. 2026-11-17.");
        }
        if (date.isAfter(LocalDate.now())) {
            throw new IllegalArgumentException("Date joined cannot be in the future.");
        }
        return date;
    }
}

// this file is the firewall of the app to cover input validation and error handling. Everything typed in by the user goes through this file before accessing the database

// the error handling is arranged according to the text fields, so name sstarts, email.... like that like that till date, each with their own validations and pre-defined rulebooks